{"code": "# Check the images directory for available image files
import os
img_dir = 'data/images-after-converted_small'
all_images = []

for laterality_view in ['R-CC', 'L-MLO', 'L-CC', 'R-MLO']:
    subdir = os.path.join(img_dir, laterality_view)
    if os.path.exists(subdir):
        images = os.listdir(subdir)
        for img in images:
            if img.endswith('.png'):
                # Parse laterality and view_position from directory name
                parts = laterality_view.split('-')
                laterality = parts[0]
                view_position = parts[1]
                image_id = img.replace('.png', '')
                all_images.append({
                    'laterality': laterality,
                    'view_position': view_position,
                    'image_id': image_id
                })

print(f"Found {len(all_images)} images")
print("Sample entries:")
for i, entry in enumerate(all_images[:5]):
    print(f"  {i+1}. {entry}")"}

